pb.RANGE_SHARE,pb.ABILITY_UPTIME=0.7,0.25
pb._model={}
function pb.model(ks,ls,ms)
local ns=tostring(ks)..jcf[2801]..tostring(ms and ms.atk)..jcf[2801]..tostring(ms and ms.cd)
local ps=pb._model[ns]
if ps~=nil then
return ps or nil
end
local qs,rs={},false
local ss=math.max(0.3,tonumber(ms and ms.cd)or 2)
local ts=math.min(1,(tonumber(ls and ls.n)or 1)/4)
local us,vs=pcall(pb.guess,ks)
local ws,xs={},{}
for ys,zs in ipairs(us and type(vs)==jcf[2659]and vs or{})do
if zs.hand then
ws[zs.pid]=true
end
xs[zs.pid]=zs.nums
end
for As,Bs in pairs(pb.rules(ks))do
if not ws[As]then
local Cs={}
for Ds,Es in pairs(type(xs[As])==jcf[2659]and xs[As]or{})do
Cs[Ds]=Es
end
for Fs,Gs in pairs(type(Bs.nums)==jcf[2659]and Bs.nums or{})do
Cs[Fs]=Gs
end
local Hs=Bs.trigger~=nil and tostring(Bs.trigger):find(jcf[3079],1,true)~=nil
if Bs.family==jcf[2861]then
local Is=(Hs and pb.ABILITY_UPTIME or 1)*(Bs.who==jcf[2929]and pb.RANGE_SHARE or 1)
local Js=qs.aura or{typed={}}
for Ks,Ls in pairs(type(Cs.typed)==jcf[2659]and Cs.typed or{})do
Js.typed[Ks]=math.max(Js.typed[Ks]or 0,(tonumber(Ls)or 0)*Is)
end
local Ms=tonumber(Cs.dmgMax)or tonumber(Cs.dmg)
if Ms then
Js.dmg=math.max(Js.dmg or 0,Ms*Is)
end
if Cs.crit then
Js.crit=math.max(Js.crit or 0,(tonumber(Cs.crit)or 0)*Is)
end
qs.aura,rs=Js,true
elseif Bs.family==jcf[2858]then
local Ns=pb.KW[tostring(Bs.keyword or jcf[1575])]
local Os=tonumber(Cs.chance)or 1
local Ps=tonumber(Cs.secsSeen)or tonumber(Cs.secs)or 5
local Qs=Cs.keep or Cs.keepSeen
local Rs=Qs and math.min(1,Os*4)or math.min(1,Ps*Os/ss)
if Hs then
Rs=math.min(Rs,Ps/60)
end
if Ns and Ns.kind==jcf[2848]and not(type(Cs.shred)==jcf[2659])then
local Ss=tonumber(Cs.amp)
local Ts=ls and((type(ls.ampTypes)==jcf[2659]and ls.ampTypes[Ns.dtype])or(tonumber(ls.amp)or 0)>0)
if Ss and Ss>0 and not Ts then
qs.fx,rs=(qs.fx or 0)+Ss*V.TYPED_AMP_SHARE*Rs*ts,true
end
elseif Ns and(Ns.kind==jcf[2794]or Ns.kind==jcf[2856])then
if not(ls and((tonumber(ls.stun)or 0)>0 or(tonumber(ls.slowTime)or 0)>0))then
qs.stun=(Ns.kind==jcf[2856]and 0.5 or 1)*Ps
if Cs.slow then
qs.slowP,qs.slowT=tonumber(Cs.slow),Ps
end
rs=true
end
elseif Ns and Ns.kind==jcf[2796]then
if not(ls and(tonumber(ls.slowTime)or 0)>0)then
qs.slowP,qs.slowT,rs=tonumber(Cs.slow)or tonumber(Cs.slowSeen)or 0.3,Ps,true
end
elseif Ns and Ns.kind==jcf[2855]then
local Us=tonumber(Cs.dot)or 0
if Us>0 and(tonumber(ls and ls.dot)or 0)<Us*0.5 then
local Vs=math.min(1.5,Us)*Os
qs.dot,rs=(qs.dot or 0)+Vs,true
if tostring(Bs.keyword)==jcf[2499]then
qs.burnDot=(qs.burnDot or 0)+Vs
end
end
end
if type(Cs.ampFrom)==jcf[2659]and tostring(Cs.ampFrom.kind)==jcf[2499]and(tonumber(Cs.ampFrom.amp)or 0)>0 then
local Ws=(type(Cs.secsBy)==jcf[2659]and#Cs.secsBy>0)and Cs.secsBy or{tonumber(Cs.secsSeen)or tonumber(Cs.secs)or 5}
qs.flames,rs={amp=tonumber(Cs.ampFrom.amp),secs=Ws},true
end
elseif Bs.family==jcf[2915]then
qs.exec,rs=tonumber(Cs.below)or 0.25,true
end
end
end
pb._model[ns]=rs and qs or false
return rs and qs or nil
end
