local Py,Qy,Ry={},{},0
for Sy,Ty in pairs(Oy)do
local Uy=type(Ty)==jcf[2659]and type(Ty.override_stats)==jcf[2659]and(Ty.override_stats[1]or Ty.override_stats[jcf[3115]])or nil
if type(Uy)==jcf[2659]then
local Vy=tonumber(Uy.health)or 20
