table.insert(Py,{hp=Vy,st=Uy})
for Wy in pairs(Uy)do
local Xy=tostring(Wy):match(jcf[2823])or tostring(Wy):match(jcf[3116])
if Xy then
Qy[Xy]=true
end
end
end
end
if not next(Qy)or Ry<=0 then
return nil
end
local Yy={weak={},strong={},res={}}
for Zy in pairs(Qy)do
local _y=0
for az,bz in ipairs(Py)do
