end
Xkb[_kb.id]=alb
local blb,clb=pcall(V.elem,_kb.id,type(Qkb)==jcf[2659]and type(Qkb.weak)==jcf[2659]and{weak=Qkb.weak,strong=Qkb.strong or{},res=Qkb.res}or nil)
