function kb.xpGuess(wnb)
local xnb=wnb.level and N.Levels[wnb.level]
if not xnb then
return 0
end
local ynb=math.min(9,tonumber(xnb.story_world_rank)or tonumber(wnb.rank)or 9)
local znb=tonumber(xnb.story_level_rank)or 6
local Anb=(wnb.kind==jcf[2708]and 1.5 or 1)*(ynb>5 and 2 or 1)
local Bnb=2.1564^(ynb-1)*(40+10*znb)/Anb
if wnb.kind==jcf[2684]then
Bnb=3*30*2.1564^(ynb-1)/Anb
end
local Cnb=ynb>=9 and 0.3 or(ynb>=7 and 0.5 or 1)
return Bnb*Cnb*6
end
