while U.now()-nob<4 and(tonumber((cob.collection:get_unit_by_uuid(bob.uuid)or dob).xp)or 0)<=iob do
task.wait(0.25)
end
local oob=cob.collection:get_unit_by_uuid(bob.uuid)or dob
local pob=(tonumber(oob.xp)or 0)-iob
if pob>0 then
local qob=kb.level(oob)
local rob=qob>kob and string.format(jcf[3824],kob,qob)or string.format(jcf[3825],kob)
cb.add(string.format(jcf[3831],hob,bob.name),hob,jcf[3832],string.format(jcf[3833],U.fmt(pob),rob))
kb.note(string.format(jcf[3834],bob.name,hob,U.fmt(pob),rob,math.abs(pob-gob)>gob*0.1 and string.format(jcf[3835],U.fmt(gob))or jcf[1575]))
else
kb.note(string.format(jcf[3836],bob.name,tostring(lob and mob or jcf[3232])))
F.backoff(jcf[3822],600)
end
end
end
