tvb.ok=true
end
end
tvb.pending=nil
F.log(1,jcf[4012],string.format(jcf[4013],jvb.label,V.name(kvb.id),tvb.out and(jcf[4014]..V.name(tvb.out))or jcf[1575],tvb.ok and string.format(jcf[4015],math.floor((ib.perRun(jvb.key,kvb.id)or 0)+0.5),kvb.what,tvb.minutes,tvb.ownMin)or tostring(tvb.why)))
F.saveSoon()
