function ab.partyChase(LOb,MOb)
local NOb,OOb=U.now(),-999
while F.alive and U.now()-NOb<(MOb or 75)do
local POb=U.now()-OOb>=15
if POb then
OOb=U.now()
end
local QOb,ROb,SOb=ab.partyFind(LOb,POb)
if ROb then
return ab.partyGo(QOb,ROb,SOb)
end
task.wait(2)
end
return false
end
