if qoc.aliveLvl and ooc.ld and(ooc.ld.id or ooc.key==jcf[3322])and qoc.aliveLvl~=gb.levelTag(ooc.ld)then
return nil
end
local uoc=gb.run(ooc,poc,{hpMul=1})
