gb.GROWN_LEVEL,gb.GROWN_MIN=50,6
function gb.grownKinds()
local Coc=N.session()
local Doc,Eoc={},0
for Foc,Goc in pairs(Coc.profile_data.collection.owned_units)do
local Hoc=Goc.unit_id
if not Doc[Hoc]and N.Units[Hoc]and not V.isFarm(Hoc)and V.rows(Hoc)and not V.hidden(Hoc)then
local Ioc,Joc=pcall(N.USC.calculate_level,Hoc,tonumber(Goc.xp)or 0)
if Ioc and(tonumber(Joc)or 0)>=gb.GROWN_LEVEL then
Doc[Hoc]=true
Eoc=Eoc+1
end
end
end
return Eoc
end
gb.EVO_KEEP=0.5
function gb.dropUnevolved(Koc,Loc)
local Moc={}
for Noc,Ooc in pairs(Koc)do
local Poc,Qoc=Loc(Noc),0
while Poc and Qoc<4 do
local Roc=Koc[Poc]
if Roc and(tonumber(Roc.sc)or 0)>=gb.EVO_KEEP*(tonumber(Ooc.sc)or 0)then
Moc[Noc]=Poc
break
end
Poc,Qoc=Loc(Poc),Qoc+1
end
end
for Soc in pairs(Moc)do
Koc[Soc]=nil
end
return Moc
end
function gb.pool(Toc,Uoc)
