local epc=N.Units[apc.unit_id]and V.rows(apc.unit_id)and V.isFarm(apc.unit_id)and V.farm(apc,V.rows(apc.unit_id).max)<=0
if N.Units[apc.unit_id]and V.rows(apc.unit_id)and not V.hidden(apc.unit_id)and dpc and not epc then
local fpc=V.isFarm(apc.unit_id)
local gpc,hpc=pcall(fpc and function()
return V.farm(apc,V.rows(apc.unit_id).max)
end or V.score,apc,Toc)
hpc=(gpc and hpc or 0)*(fpc and 1 or V.skinMul(apc,Uoc and Uoc.skinSet)*V.eventMul(apc,Uoc and Uoc.ld))
local ipc=fpc and Xoc or Woc
if not ipc[apc.unit_id]or hpc>ipc[apc.unit_id].sc then
ipc[apc.unit_id]={u=apc,sc=hpc}
end
