local function jpc(kpc)
local lpc=N.Units[kpc]
local mpc=type(lpc)==jcf[2659]and type(lpc.evolve)==jcf[2659]and lpc.evolve.evolve_unit or nil
return mpc~=kpc and mpc or nil
end
pcall(gb.dropUnevolved,Woc,jpc)
pcall(gb.dropUnevolved,Xoc,jpc)
local opc,ppc={},{}
for qpc,rpc in pairs(Woc)do
table.insert(opc,rpc)
end
for spc,tpc in pairs(Xoc)do
table.insert(ppc,tpc)
end
table.sort(opc,function(upc,vpc)
return upc.sc>vpc.sc
end)
table.sort(ppc,function(wpc,xpc)
return wpc.sc>xpc.sc
end)
local ypc={}
for zpc=1,math.min(10,#opc)do
table.insert(ypc,opc[zpc].u)
end
local Apc,Bpc={},{}
for Cpc=11,#opc do
local Dpc=V.rows(opc[Cpc].u.unit_id)
for Epc=0,Dpc.max do
if Dpc[Epc]and Dpc[Epc].atk and V.attackInfo(Dpc[Epc].atk,Dpc[Epc].range).dot>0 then
table.insert(Epc==0 and Apc or Bpc,opc[Cpc].u)
break
end
end
end
for Fpc=1,math.min(4,#Apc)do
table.insert(ypc,Apc[Fpc])
end
for Gpc=1,math.min(2,#Bpc)do
table.insert(ypc,Bpc[Gpc])
end
for Hpc=1,math.min(3,#ppc)do
table.insert(ypc,ppc[Hpc].u)
end
local Ipc={}
for Jpc=11,#opc do
local Kpc=V.rows(opc[Jpc].u.unit_id)[0]
local Lpc=Kpc and Kpc.atk and V.attackInfo(Kpc.atk,Kpc.range)
if Lpc and(Lpc.slowTime>0 or Lpc.stun>0)then
table.insert(Ipc,opc[Jpc].u)
end
end
for Mpc=1,math.min(3,#Ipc)do
table.insert(ypc,Ipc[Mpc])
end
for Npc=11,#opc do
local Opc=opc[Npc].u.unit_id
if V.allyBuff(Opc)or V.BLESS.by[Opc]or V.GALE[Opc]then
table.insert(ypc,opc[Npc].u)
end
end
if Uoc and(Uoc.shield or 0)>0 then
for Ppc=11,#opc do
if V.breaksShields(opc[Ppc].u.unit_id)then
table.insert(ypc,opc[Ppc].u)
end
end
end
if Uoc and(tonumber(Uoc.regen)or 0)>0 then
for Qpc=11,#opc do
local Rpc,Spc=pcall(V.bleeds,opc[Qpc].u.unit_id)
if Rpc and Spc and not V.breaksShields(opc[Qpc].u.unit_id)then
table.insert(ypc,opc[Qpc].u)
end
end
end
if Uoc and((Uoc.flyChance or 0)>0 or Uoc.mapFly or(Uoc.shield or 0)>0)then
local Tpc,Upc={},{}
for Vpc=11,#opc do
local Wpc=opc[Vpc].u
local Xpc=V.rows(Wpc.unit_id)[0]
if V.airFrom(Wpc.unit_id)==0 then
table.insert(Tpc,Wpc)
end
local Ypc,Zpc=tonumber(Xpc and Xpc.cd)or 0,tonumber((N.Units[Wpc.unit_id]or{}).cost)or 0
if Ypc>0 and Zpc>0 and V.range(Wpc,0)>=15 then
local _pc=V.attackInfo(Xpc.atk,Xpc.range)
table.insert(Upc,{u=Wpc,v=_pc.n*_pc.hits/Ypc/Zpc*math.min(6,V.cap(Wpc))})
end
end
table.sort(Upc,function(aqc,bqc)
return aqc.v>bqc.v
end)
for cqc=1,math.min(4,#Tpc)do
table.insert(ypc,Tpc[cqc])
end
for dqc=1,math.min(6,#Upc)do
table.insert(ypc,Upc[dqc].u)
end
end
local eqc,fqc={},{}
for gqc,hqc in ipairs(ypc)do
if not eqc[hqc]then
eqc[hqc]=true
table.insert(fqc,hqc)
end
end
fqc.rest={}
for iqc,jqc in ipairs(opc)do
if not eqc[jqc.u]then
table.insert(fqc.rest,jqc.u)
end
end
return fqc
end
function gb.objective(kqc)
if kqc.kscore then
return(tonumber(kqc.kills)or 0)+kqc.wave*0.01
end
return(kqc.won and 1000 or 0)+kqc.wave*10-(kqc.won and kqc.t/60 or((kqc.left or 1)*9-math.min(9,kqc.t/60)))
end
gb.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
function gb.cliff(lqc,mqc,nqc)
local oqc
for pqc,qqc in ipairs(gb.LADDER)do
oqc=gb.run(lqc,mqc,{hpMul=qqc,layout=nqc})
if not oqc.won then
return qqc,oqc
end
end
return gb.LADDER[#gb.LADDER],oqc
end
gb.TEAM_FASTER,gb.TEAM_FASTER_S=0.05,15
function gb.teamFaster(rqc,sqc,tqc)
if rqc.infinite or rqc.timeLimit or type(tqc)~=jcf[2659]or not tqc.won or not tonumber(tqc.minutes)then
return nil
end
local uqc=gb.teamFrom(sqc,rqc.map)
local vqc=gb.run(rqc,uqc,{hpMul=1})
if not(vqc and vqc.won)then
return nil
end
local wqc=gb.run(rqc,uqc,{hpMul=1.3})
if not(wqc and wqc.won)then
return nil
end
local xqc,yqc=tonumber(tqc.minutes)*60,tonumber(vqc.t)or math.huge
if yqc<=xqc*(1-gb.TEAM_FASTER)and xqc-yqc>=gb.TEAM_FASTER_S then
return{mine=xqc,pick=yqc}
end
return nil
end
function gb.exam(zqc,Aqc)
local Bqc,Cqc,Dqc=gb.teamFrom(Aqc,zqc.map),0,0
for Eqc,Fqc in ipairs(gb.LADDER)do
local Gqc,Hqc=0,0
for Iqc,Jqc in ipairs({0.92,1,1.08})do
local Kqc=gb.run(zqc,Bqc,{hpMul=Fqc*Jqc})
if Kqc.won then
Gqc=Gqc+1
end
Hqc=Hqc+Kqc.wave
end
Cqc,Dqc=Cqc+Gqc,Hqc/3
task.wait()
if Gqc==0 then
