if not Qqc and Sqc and(tonumber(Sqc.wins)or 0)>0 and Tqc==0 and Mqc.key~=jcf[3409]and Mqc.key~=jcf[3405]then
return false
end
local Uqc=Qqc~=nil or Tqc>0
