for jrc,krc in ipairs(gb.LADDER)do
local lrc,mrc=0,0
for nrc,orc in ipairs({0.92,1,1.08})do
local prc=gb.run(crc,erc,{hpMul=krc*orc})
if prc.won then
lrc=lrc+1
end
mrc=mrc+prc.wave
end
frc,irc=frc+lrc,mrc/3
if krc==1 then
grc,hrc=lrc,mrc/3
end
task.wait()
if lrc==0 then
break
