function bb.buildPath()
bb.samples={}
local hOc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not hOc then
return
end
for iOc,jOc in pairs(hOc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[iOc.Name])then
local kOc={}
for lOc,mOc in ipairs(jOc.points or{})do
table.insert(kOc,mOc.part.Position)
end
local nOc=0
for oOc=2,#kOc do
nOc=nOc+(kOc[oOc]-kOc[oOc-1]).Magnitude
end
local pOc=0
for qOc=2,#kOc do
local rOc,sOc=kOc[qOc-1],kOc[qOc]
local tOc=(sOc-rOc).Magnitude
local uOc=math.max(1,math.floor(tOc/2))
for vOc=0,uOc-1 do
local wOc=rOc:Lerp(sOc,vOc/uOc)
table.insert(bb.samples,{pos=wOc,prog=(pOc+tOc*vOc/uOc)/math.max(1,nOc),lane=iOc.Name})
end
pOc=pOc+tOc
end
if kOc[#kOc]then
table.insert(bb.samples,{pos=kOc[#kOc],prog=1,lane=iOc.Name})
end
end
end
pcall(bb.readHidden,hOc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local xOc=tonumber(bb.ld and bb.ld._portal_lanes)
local yOc=gb.laneList(bb.samples)
if xOc and xOc>=1 and yOc and#yOc>xOc then
bb.laneWant=xOc
end
bb.laneTotal=yOc and#yOc or 1
bb.countLanes()
end
function bb.readHidden(zOc)
local AOc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(AOc)~=jcf[2659]or not next(AOc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local BOc
for COc,DOc in pairs(zOc)do
if AOc[COc.Name]and type(DOc.points)==jcf[2659]and#DOc.points>=2 then
local EOc={}
for FOc,GOc in ipairs(DOc.points)do
EOc[FOc]=U.flat(GOc.part.Position)
end
local HOc={}
for IOc,JOc in ipairs(bb.samples)do
local KOc=tostring(JOc.lane)
HOc[KOc]=HOc[KOc]or{}
table.insert(HOc[KOc],JOc)
end
local LOc,MOc
for NOc,OOc in pairs(HOc)do
local POc=0
for QOc=1,#EOc,math.max(1,math.floor(#EOc/20))do
local ROc=math.huge
for SOc,TOc in ipairs(OOc)do
local UOc=(U.flat(TOc.pos)-EOc[QOc]).Magnitude
if UOc<ROc then
ROc=UOc
end
end
POc=POc+ROc
end
if not MOc or POc<MOc then
LOc,MOc=NOc,POc
end
end
local VOc,WOc,XOc,YOc,ZOc,_Oc={},nil,nil,nil,0,0
for aPc,bPc in ipairs(EOc)do
local cPc,dPc=nil,math.huge
for ePc,fPc in ipairs(HOc[LOc])do
local gPc=(U.flat(fPc.pos)-bPc).Magnitude
if gPc<dPc then
dPc,cPc=gPc,fPc.prog
end
end
_Oc=math.max(_Oc,dPc)
if XOc then
local hPc=cPc-XOc
local iPc=(hPc>0.002 and 1)or(hPc< -0.002 and-1)or YOc
if YOc and iPc and iPc~=YOc then
table.insert(VOc,math.floor(XOc*1000+0.5)/1000)
end
YOc,ZOc=iPc or YOc,ZOc+math.abs(hPc)
else
WOc=cPc
end
XOc=cPc
if aPc%50==0 then
task.wait()
end
end
if XOc and _Oc<=8 then
table.insert(VOc,math.floor(XOc*1000+0.5)/1000)
BOc=BOc or{}
