if not F.alive then
return
end
local YPc=N.prof()
local ZPc=YPc and YPc.daily_infinite_reward_claims and YPc.daily_infinite_reward_claims[bb.ld.id]
local _Pc=type(ZPc)==jcf[2659]and(tonumber(ZPc.highest_claimed_wave)or 0)>=XPc and os.time()-(tonumber(ZPc.highest_claim_time)or 0)<900
