if dTc.Magnitude<0.01 then
dTc=Vector3 .new(1,0,0)
end
dTc=dTc.Unit
local eTc=Vector3 .new(-dTc.Z,0,dTc.X)
for fTc,gTc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for hTc,iTc in ipairs({1,-1})do
local jTc=bTc.pos+eTc*gTc*iTc
local kTc=string.format(jcf[5028],math.floor(jTc.X/1.5),math.floor(jTc.Z/1.5))
if not _Sc[kTc]then
_Sc[kTc]=true
table.insert(bb.cands,jTc)
