function bb.coverage(lTc,mTc)
local nTc={}
for oTc,pTc in ipairs(lTc)do
local qTc=pTc._stats
if not V.isFarm(qTc.id.Value)and qTc:FindFirstChild(jcf[2929])then
table.insert(nTc,{p=U.flat(pTc:GetPivot().Position),r=qTc.range.Value*(V.SUMMONER[qTc.id.Value]and V.SUMMONER[qTc.id.Value].reach or 1),air=bb.canAir(pTc)})
end
end
local rTc,sTc=0,0
if#nTc>0 then
for tTc,uTc in ipairs(bb.samples)do
if uTc.prog>sTc then
local vTc=U.flat(uTc.pos)
for wTc,xTc in ipairs(nTc)do
if(vTc-xTc.p).Magnitude<=xTc.r then
if uTc.prog>rTc then
rTc=uTc.prog
end
if xTc.air then
sTc=uTc.prog
break
end
end
end
end
end
end
local yTc,zTc={},bb.laneCount
if zTc and zTc.n>=2 and#nTc>0 then
local ATc={}
for BTc,CTc in ipairs(bb.samples)do
local DTc=U.flat(CTc.pos)
for ETc,FTc in ipairs(nTc)do
if(DTc-FTc.p).Magnitude<=FTc.r then
local GTc=tostring(CTc.lane)
ATc[GTc]=(ATc[GTc]or 0)+1
if CTc.prog>(yTc[GTc]or 0)then
yTc[GTc]=CTc.prog
end
break
end
end
end
local HTc,ITc={},0
for JTc,KTc in pairs(zTc.by)do
HTc[JTc]=(ATc[JTc]or 0)/math.max(1,KTc)
ITc=math.max(ITc,HTc[JTc])
end
bb.laneW={}
for LTc,MTc in pairs(zTc.by)do
bb.laneW[LTc]=(zTc.avg/math.max(1,MTc))*(1+1.5*(ITc>0 and(1-HTc[LTc]/ITc)or 0))
end
bb.laneFrac=HTc
else
bb.laneW,bb.laneFrac=nil,nil
end
local NTc,OTc,PTc
if#nTc>0 then
for QTc,RTc in ipairs(mTc)do
local STc=(bb.laneW and RTc.lane)and(yTc[tostring(RTc.lane)]or 0)or rTc
if RTc.hp>0 and RTc.prog>STc+0.02 and RTc.prog>(NTc or 0)then
NTc,PTc=RTc.prog,bb.laneW and RTc.lane or nil
end
if RTc.hp>0 and RTc.fly and RTc.prog>sTc+0.02 then
OTc=true
end
end
end
local TTc= #nTc>0 and(bb.pressure or 0)>=rTc-0.08
local UTc
if#nTc>0 and bb.killZone()then
local VTc= #nTc
for WTc,XTc in ipairs(nTc)do
VTc=VTc+XTc.r+XTc.p.X*0.01+XTc.p.Z*0.001
end
if bb._boxSig~=VTc then
local YTc={}
for ZTc,_Tc in ipairs(bb.samples)do
local aUc,bUc=U.flat(_Tc.pos),0
for cUc,dUc in ipairs(nTc)do
if(aUc-dUc.p).Magnitude<=dUc.r then
bUc=bUc+1
end
end
if bUc>0 then
table.insert(YTc,{p=_Tc.prog,w=bUc})
end
end
bb._boxSig,bb._boxFrom=VTc,eb.boxFrom(YTc)
end
UTc=bb._boxFrom
end
return{covEnd=rTc,airEnd=sTc,leak=NTc,leakLane=PTc,covL=yTc,airLeak=OTc,push=TTc,units= #nTc,boxFrom=UTc}
end
