function bb.studyRun(nad)
local oad=U.now()
while F.alive and not(bb.finished or bb.result)and(bb.planning or U.now()-oad<20)do
task.wait(1)
end
local function qad()
return F.alive and not(bb.finished or bb.result)and O.mapStudy~=false and not O.lowLag and F.where==jcf[2740]
end
if not qad()then
return
end
local rad,sad,tad=nad.info,nad.team,nad.base
local uad=rad.timeLimit~=nil
local vad=uad and 1 or math.max(1,tonumber(nad.hard)or 1)
local wad={vad*0.95,vad*1.05}
local xad=bb.bookFor(rad)
local yad={key=nad.key,label=bb.label(),n=xad and tonumber(xad.n)or 0,run=0,timed=uad,kills=rad.killScore and true or nil,hp=vad,at=os.time()}
bb.study=yad
