for Ead,Fad in ipairs(nad.attackers)do
local Gad,Had,Iad,Jad=bb.studyMoves(Fad,nad.scale)
zad[Fad.id]=Gad
Aad,Bad,Cad,Dad=Aad+ #(Fad.spots or{}),Bad+Had,Cad+ #Gad,Dad+Jad
if not qad()then
return
end
end
yad.moves=Cad
F.log(1,jcf[3481],string.format(jcf[5189],yad.label,Aad,Bad,Cad,Dad>0 and string.format(jcf[5190],Dad)or jcf[1575]))
local Kad={}
local function Lad(Mad)
return{samples=bb.samples,cache=Kad,spots=Mad,style=tad.style,list=tad.list,hybridHill=tad.hybridHill}
end
local function Nad(Oad)
local Pad=0
for Qad,Rad in pairs(Oad)do
local Sad=bb.spotRec(Qad,Rad)
if Sad then
Pad=Pad+(tonumber(Sad.wins)or 0)*200-((tonumber(Sad.runs)or 0)-(tonumber(Sad.wins)or 0))*1500
end
end
return Pad
end
local function Tad(Uad)
local Vad,Wad,Xad=0,0,0
for Yad,Zad in ipairs(wad)do
local _ad=os.clock()
local abd=gb.runRaw(rad,sad,{hpMul=Zad,layout=Lad(Uad),bg=true})
Vad,Wad,Xad=Vad+gb.objective(abd),Wad+(tonumber(abd.kills)or 0),Xad+(tonumber(abd.wave)or 0)
task.wait(math.clamp((os.clock()-_ad)*3,0.25,nad.pauseMax or 1.5))
if not qad()then
return nil
end
end
yad.n,yad.run=yad.n+1,yad.run+1
return Vad/ #wad*100+Nad(Uad),Wad/ #wad,Xad/ #wad
end
local function bbd(cbd)
local dbd={}
for ebd,fbd in pairs(cbd)do
dbd[ebd]=fbd
end
return dbd
end
local function gbd(hbd,ibd,jbd)
for kbd,lbd in pairs(hbd)do
if kbd~=ibd and(U.flat(lbd)-U.flat(jbd)).Magnitude<4.5 then
return true
end
end
return false
end
local mbd={spots=bbd(tad.spots)}
mbd.s,mbd.kills,mbd.wave=Tad(mbd.spots)
