end
yad.baseKills,yad.baseWave=mbd.kills,mbd.wave
yad.bestKills,yad.bestWave=mbd.kills,mbd.wave
if xad and xad.aside==nil then
local nbd,obd=bbd(mbd.spots),0
for pbd,qbd in ipairs(nad.attackers)do
local rbd=xad.spots[qbd.id]
local sbd=type(rbd)==jcf[2659]and tonumber(rbd[1])and tonumber(rbd[3])and bb.nearSpot(qbd.spots,tonumber(rbd[1]),tonumber(rbd[3]))or nil
if sbd and sbd~=nbd[qbd.id]and not gbd(nbd,qbd.id,sbd)then
nbd[qbd.id]=sbd
obd=obd+1
