local tbd,ubd,vbd=Tad(nbd)
if not tbd then
return bb.studyEnd(yad,nad,mbd)
end
if tbd>mbd.s then
mbd={spots=nbd,s=tbd,kills=ubd,wave=vbd}
yad.bestKills,yad.bestWave=ubd,vbd
end
end
end
local wbd,xbd=U.now(),yad.run
local function ybd(zbd)
