F.log(1,jcf[3481],bb.studyWords(yad))
end
end
local Bbd={mbd}
for Cbd,Dbd in ipairs(nad.attackers)do
local Ebd={}
for Fbd,Gbd in ipairs(Bbd)do
table.insert(Ebd,Gbd)
for Hbd,Ibd in ipairs(zad[Dbd.id]or{})do
if Ibd~=Gbd.spots[Dbd.id]and not gbd(Gbd.spots,Dbd.id,Ibd)then
local Jbd=bbd(Gbd.spots)
