local Rbd={}
for Sbd,Tbd in ipairs(nad.attackers)do
if zad[Tbd.id]and#zad[Tbd.id]>0 then
table.insert(Rbd,Tbd.id)
end
end
while qad()and#Rbd>0 do
local Ubd=bbd(mbd.spots)
for Vbd=1,math.min(2,#Rbd)do
local Wbd=Rbd[math.random(#Rbd)]
local Xbd=zad[Wbd]
local Ybd=Xbd[math.random(#Xbd)]
if not gbd(Ubd,Wbd,Ybd)then
Ubd[Wbd]=Ybd
end
end
local Zbd,_bd,acd=Tad(Ubd)
if not Zbd then
break
end
ybd({spots=Ubd,s=Zbd,kills=_bd,wave=acd})
Abd()
end
bb.studyEnd(yad,nad,mbd)
end
bb.STUDY_INF_WAIT=240
function bb.validOpen(bcd,ccd)
local dcd=N.PC.raycast(bcd+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not dcd then
return nil
end
if not N.PC.is_valid_raycast_hit(dcd.Instance,ccd)then
return nil
end
local ecd=dcd.Position
if bb.blockedSpot(ecd)then
return nil
end
local fcd=(tonumber(ccd.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(fcd*2,2.5,fcd*2)
bb.probe.CFrame=CFrame.new(ecd+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return ecd
end
function bb.studyInfinite()
if O.mapStudy==false or O.lowLag or not(bb.info and bb.infinite)or bb.kind==jcf[3131]then
return
end
local gcd=bb.info
