if Eod and Fod then
if Dod and Dod>=(tonumber(P.caps[xod.uuid])or math.huge)then
F.log(1,jcf[5035],string.format(jcf[5254],V.name(xod.id),tostring(P.caps[xod.uuid])))
P.caps[xod.uuid],P.capsAt[xod.uuid]=nil,nil
F.saveSoon()
end
bb.spent=bb.spent+(xod.data.cost or 0)
table.insert(bb.actions,string.format(jcf[5255],V.name(xod.id)))
