bb.placeLog=bb.placeLog or{}
table.insert(bb.placeLog,{t=math.floor(U.now()-(bb.startT or U.now())),w=bb.wave(),id=xod.id,x=math.floor(Aod.X),z=math.floor(Aod.Z),cover=math.floor((Bod or 0)+0.5),why=tostring(yod):sub(1,90)})
F.status(jcf[5099],string.format(jcf[5257],V.name(xod.id),yod))
bb.placedAt=bb.placedAt or{}
bb.placedAt[xod.uuid]=(bb.placedAt[xod.uuid]or 0)+1
return true
end
if Cod>=(xod.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[xod.uuid]=(bb.placeFail[xod.uuid]or 0)+1
if bb.placeFail[xod.uuid]>=2 then
bb.noSpot[xod.uuid]=3
if bb.noSpotField then
bb.noSpotField[xod.uuid]=nil
end
F.log(1,jcf[5035],string.format(jcf[5258],V.name(xod.id),bb.fieldCount(),bb.FIELD_MAX))
end
end
if Eod and Cod>=(xod.data.cost or 0)and not bb.random then
local God=bb.spotKey(Aod)
bb.refused[God]=true
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[xod.uuid]=(bb.unitRefusals[xod.uuid]or 0)+1
if not bb.crowded()then
local Hod=bb.mapKey()
P.blocked[Hod]=P.blocked[Hod]or{}
if not bb.refusedRun[God]then
P.blocked[Hod][God]=(tonumber(P.blocked[Hod][God])or 0)+1
bb.refusedRun[God]=true
P.blockedAt[Hod]=P.blockedAt[Hod]or{}
P.blockedAt[Hod][God]=os.time()
end
if bb.unitRefusals[xod.uuid]>=3 then
local Iod=math.max(1,bb.count(xod.uuid))
if P.caps[xod.uuid]~=Iod or not V.learnedCap(xod.uuid)then
P.caps[xod.uuid],P.capsAt[xod.uuid]=Iod,os.time()
F.log(1,jcf[5035],string.format(jcf[5259],V.name(xod.id),Iod))
end
end
elseif bb.unitRefusals[xod.uuid]>=3 and(bb.noSpot[xod.uuid]or 0)<3 then
