end
table.insert(bb.trialTrace,string.format(jcf[5263],Tod,Sod-(bb.startT or Sod),Uod,table.concat(Wod,jcf[3382]),Yod,Xod+dpd,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[Tod-1]or 0,bb.teamDps or 0))
end
if Qod.lastW and Qod.lastW>0 and Qod.lastWT then
table.insert(Qod.waveSec,Sod-Qod.lastWT)
end
if Qod.paidT and Tod>0 and Sod-Qod.paidT<15 then
table.insert(Qod.skip,Sod-Qod.paidT)
end
Qod.paidT=nil
if Tod>0 then
Qod.alive[tostring(Tod)]=bb.hpAliveRaw or 0
end
Qod.lastW,Qod.lastWT=Tod,Sod
end
