local vpd=upd*Rod.hpRaw*gb.waveScale(Rod,Tod,Rod.list[Tod])
if vpd>0 and spd.MaxHealth>0 then
table.insert(Qod.hp,spd.MaxHealth/vpd)
end
end
bb.track[ppd]={t=Sod,p=opd.prog,sp=(rpd:FindFirstChild(jcf[5265])and tonumber(rpd.speed.Value))or 1}
if spd and spd.MaxHealth>0 then
