if Qod.potWin>0 and Ppd>=0 then
Qod.dealtSum=(Qod.dealtSum or 0)+Ppd
Qod.potSum=Qod.potSum+Qod.potWin
end
Qod.winT,Qod.winDealt,Qod.potWin=Sod,xpd,0
end
end
if not Qod.winT then
Qod.winT,Qod.winDealt=Sod,xpd
end
Qod.lastDealtT=Sod
if Tod~=Qod.dpsW and Tod>0 then
Qod.dpsAt[tostring(Tod)]=bb.teamDps or 0
Qod.dpsW=Tod
end
local Qpd=math.min(1,Sod-(Qod.densT or Sod))
Qod.densT=Sod
for Rpd,Spd in ipairs(bb.enemies)do
local Tpd=math.min(gb.BINS,math.floor(Spd.prog*gb.BINS)+1)
Qod.dens[Tpd]=(Qod.dens[Tpd]or 0)+Qpd
