if bqd and bqd.v==1 and bqd.laneV and(bqd.densN or 0)>5 and(bqd.binsDensN or 0)>=5 then
return
end
local cqd={override_hitbox_radius=1.75}
local dqd={hill_unit=true,override_hitbox_radius=1.75}
