end
end
end
task.wait()
end
local Eqd=P.maps[aqd]or{}
P.maps[aqd]={v=1,laneV=1,bins=jqd,binsL=lqd and kqd or nil,lanes=lqd,hill=fqd,spots= #eqd,dens=Eqd.dens,densN=Eqd.densN,binsDensN=Eqd.densN or 0,lay=Eqd.lay,walk=Eqd.walk,walkN=Eqd.walkN,sep=lqd and(select(2,pcall(gb.laneSep,bb.samples))or Eqd.sep)or nil,hidden=Eqd.hidden}
gb._masks={}
